/// <summary>
/// Clean up service class for MET Excise Register Entry AIS table.
/// </summary>
public class METExciseRegisterAISCleanUpService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// process method which will be called from batch job. It will delete the records from METExciseRegisterEntryAIS table which are older than the specified number of days in the contract.
/// </summary>
/// <param name = "_contract">contract</param>
public void process(METExciseRegisterAISCleanUpContract _contract)
{
    int noOfDays = _contract.parmNoOfDays();
    METExciseRegisterEntryAIS   registerEntry;

    utcdatetime tillDate = DateTimeUtil::addDays(DateTimeUtil::getSystemDateTime(), -noOfDays);

    delete_from registerEntry
        where registerEntry.CreatedDateTime < tillDate;
}
